begin;
create extension if not exists pgtap with schema extensions;
select plan(24);
select public.register_relay('00000000-0000-4000-8000-0000000000d1','google-declaration-admin','[Admin]');
select public.register_relay('00000000-0000-4000-8000-0000000000a1','google-declaration-relais','[Relais]');
insert into prive.admins(id) values('00000000-0000-4000-8000-0000000000d1');
create temporary table resultat (r jsonb);grant all on resultat to authenticated;
create function pg_temp.entree(p_name text default '[École déclarée]',p_div text default null) returns jsonb language sql as $$
select jsonb_build_object('name',p_name,'campuses',jsonb_build_array(jsonb_build_object('division',p_div,'cycles',jsonb_build_array('primaire'))));
$$;
set local role anon;
select throws_ok($$select public.create_school_declaration(pg_temp.entree(),current_date,true)$$,'42501',null,'Un visiteur ne crée pas une déclaration');
select throws_ok($$select * from prive.school_declarations$$,'42501',null,'Preuve privée inaccessible');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-0000000000a1","role":"authenticated"}',true);
select throws_ok($$select public.create_school_declaration(pg_temp.entree(),current_date,true)$$,'42501',null,'Un relais ne déclare pas au nom d’une école');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-0000000000d1","role":"authenticated"}',true);
select throws_ok($$select public.create_school_declaration(pg_temp.entree(),null,true)$$,'22023',null,'Date obligatoire');
select throws_ok($$select public.create_school_declaration(pg_temp.entree(),current_date+2,true)$$,'22023',null,'Date future refusée');
select throws_ok($$select public.create_school_declaration(pg_temp.entree(),current_date,false)$$,'22023',null,'Transmission explicite obligatoire');
select throws_ok($$select public.create_school_declaration(pg_temp.entree(),current_date,null)$$,'22023',null,'Confirmation nulle refusée');
select throws_ok($$select public.create_school_declaration('{"name":"[Numéro privé]","campuses":[{"sign_phone":"242060000001"}]}',current_date,true)$$,'22023',null,'Aucun numéro de déclaration copié dans une enseigne');
insert into resultat select public.create_school_declaration(pg_temp.entree(),current_date,true);
select is((select origin::text from public.campuses where id=(select (r->'campus_ids'->>0)::uuid from resultat)),'school','Origine école conservée');
select is((select school_declared_on from public.campuses where id=(select (r->'campus_ids'->>0)::uuid from resultat)),current_date,'Date de déclaration conservée');
select is((select publication::text from public.campuses where id=(select (r->'campus_ids'->>0)::uuid from resultat)),'brouillon','Aucune publication automatique');
select ok((select surveyed_at is null and verified_on is null from public.campuses where id=(select (r->'campus_ids'->>0)::uuid from resultat)),'Aucun passage ou badge inventé');
select throws_ok($$update public.campuses set school_declared_on=current_date-1 where origin='school'$$,'42501',null,'Pas de modification de provenance sans commande');
select throws_ok($$update public.campuses set origin='field' where origin='school'$$,'42501',null,'Pas de conversion en terrain par une écriture directe');
select throws_ok($$select public.create_catalog_entry(pg_temp.entree('[Sans date]'),'school')$$,'23514',null,'Ancienne commande ne crée pas une déclaration sans date');
select throws_ok($$select * from prive.school_declarations$$,'42501',null,'Historique privé même pour les lectures API admin');
reset role;
set local role anon;
select is((select count(*)::int from public.public_campuses where origin='school'),0,'Une déclaration non publiée reste privée');
reset role;
select is((select count(*)::int from prive.school_declarations),1,'Une déclaration tracée');
select is((select recorded_by from prive.school_declarations),'00000000-0000-4000-8000-0000000000d1'::uuid,'Auteur privé enregistré');
update public.campuses set division_id=(select id from public.geo_divisions where level=3 limit 1),publication='publiee' where origin='school';
set local role anon;
select is((select school_declared_on from public.public_campuses where origin='school'),current_date,'Date accessible après publication seulement');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-0000000000d1","role":"authenticated"}',true);
select is(public.create_school_declaration(pg_temp.entree('[École déclarée]',(select division_id::text from public.campuses where origin='school')),current_date,true)->>'status','exists','Pas de doublon quand une fiche existe');
select is(public.create_catalog_entry(pg_temp.entree('[Ajout admin]'),'admin')->>'status','created','Ajout NTanova toujours possible');
select is((select origin::text from public.campuses c join public.institutions i on i.id=c.institution_id where i.name='[Ajout admin]'),'admin','Ajout NTanova ne devient pas une déclaration');
reset role;
select is((select count(*)::int from prive.school_declarations),1,'Doublon et ajout admin ne fabriquent pas de preuve école');
select * from finish();rollback;
